        # [cfg (feature = "dfa-build")] impl TransitionTable < Vec < u32 > > { # [doc = " Create a minimal transition table with just two states: a dead state"] # [doc = " and a quit state. The alphabet length and stride of the transition"] # [doc = " table is determined by the given set of equivalence classes."] fn minimal (classes : ByteClasses) -> TransitionTable < Vec < u32 > > { let mut tt = TransitionTable { table : vec ! [] , classes , stride2 : classes . stride2 () , } ; tt . add_empty_state () . unwrap () ; tt . add_empty_state () . unwrap () ; tt } # [doc = " Set a transition in this table. Both the `from` and `to` states must"] # [doc = " already exist, otherwise this panics. `unit` should correspond to the"] # [doc = " transition out of `from` to set to `to`."] fn set (& mut self , from : StateID , unit : alphabet :: Unit , to : StateID) { assert ! (self . is_valid (from) , "invalid 'from' state") ; assert ! (self . is_valid (to) , "invalid 'to' state") ; self . table [from . as_usize () + self . classes . get_by_unit (unit)] = to . as_u32 () ; } # [doc = " Add an empty state (a state where all transitions lead to a dead state)"] # [doc = " and return its identifier. The identifier returned is guaranteed to"] # [doc = " not point to any other existing state."] # [doc = ""] # [doc = " If adding a state would exhaust the state identifier space, then this"] # [doc = " returns an error."] fn add_empty_state (& mut self) -> Result < StateID , BuildError > { let next = self . table . len () ; let id = StateID :: new (next) . map_err (| _ | BuildError :: too_many_states ()) ? ; self . table . extend (iter :: repeat (0) . take (self . stride ())) ; Ok (id) } # [doc = " Swap the two states given in this transition table."] # [doc = ""] # [doc = " This routine does not do anything to check the correctness of this"] # [doc = " swap. Callers must ensure that other states pointing to id1 and id2 are"] # [doc = " updated appropriately."] # [doc = ""] # [doc = " Both id1 and id2 must point to valid states, otherwise this panics."] fn swap (& mut self , id1 : StateID , id2 : StateID) { assert ! (self . is_valid (id1) , "invalid 'id1' state: {id1:?}") ; assert ! (self . is_valid (id2) , "invalid 'id2' state: {id2:?}") ; for b in 0 .. self . classes . alphabet_len () { self . table . swap (id1 . as_usize () + b , id2 . as_usize () + b) ; } } # [doc = " Remap the transitions for the state given according to the function"] # [doc = " given. This applies the given map function to every transition in the"] # [doc = " given state and changes the transition in place to the result of the"] # [doc = " map function for that transition."] fn remap (& mut self , id : StateID , map : impl Fn (StateID) -> StateID) { for byte in 0 .. self . alphabet_len () { let i = id . as_usize () + byte ; let next = self . table () [i] ; self . table_mut () [id . as_usize () + byte] = map (next) ; } } # [doc = " Truncate the states in this transition table to the given length."] # [doc = ""] # [doc = " This routine does not do anything to check the correctness of this"] # [doc = " truncation. Callers must ensure that other states pointing to truncated"] # [doc = " states are updated appropriately."] fn truncate (& mut self , len : usize) { self . table . truncate (len << self . stride2) ; } }
